// Reads traces back from neatlogs, so Blue diagnoses a failure from what
// neatlogs actually recorded (spans, errors, and neatlogs' own detections), not
// only from Bulwark's local observation. Best-effort: traces take a while to
// finalize, and when one isn't ready in time Blue falls back to local evidence.

const ENDPOINT = () => (process.env.NEATLOGS_ENDPOINT || 'https://ingest.neatlogs.com').replace(/\/$/, '');

export interface NeatlogsTrace {
  _id: string;
  name?: string;
  status?: string;
  finalizationStatus?: string;
  hasError?: boolean;
  spans?: NeatlogsSpan[];
  detections?: unknown[];
  traceDetections?: unknown[];
  [key: string]: unknown;
}

interface NeatlogsSpan {
  node_type?: string;
  node_name?: string;
  status?: string;
  createdAt?: string;
  detections?: unknown[];
  data?: Record<string, unknown>;
}

export type Fetcher = (url: string, init: { headers: Record<string, string> }) => Promise<{ status: number; json(): Promise<unknown> }>;

/** Polls until the trace is finalized with spans, or the wait budget runs out. */
export async function readTrace(traceId: string, opts: { waitMs?: number; pollMs?: number; fetcher?: Fetcher } = {}): Promise<NeatlogsTrace | null> {
  const key = process.env.NEATLOGS_API_KEY;
  if (!key || !traceId) return null;
  const fetcher = opts.fetcher ?? (fetch as unknown as Fetcher);
  const deadline = Date.now() + (opts.waitMs ?? 30_000);
  while (true) {
    try {
      const res = await fetcher(`${ENDPOINT()}/api/traces/v3/${encodeURIComponent(traceId)}`, { headers: { 'x-api-key': key } });
      if (res.status === 401 || res.status === 403 || res.status === 404) return null;
      if (res.status === 200) {
        const trace = (await res.json()) as NeatlogsTrace;
        if (trace.spans?.length) return trace;
      }
    } catch {
      // network hiccup: keep polling until the deadline
    }
    if (Date.now() >= deadline) return null;
    await new Promise((r) => setTimeout(r, opts.pollMs ?? 3000));
  }
}

const clip = (v: unknown, n: number) => {
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return s && s.length > n ? `${s.slice(0, n)}…` : s;
};

/** A compact, model-friendly digest of a trace: detections first, then the span timeline. */
export function summarizeTrace(trace: NeatlogsTrace, maxSpans = 40): string {
  const spans = [...(trace.spans ?? [])].sort((a, b) => String(a.createdAt ?? '').localeCompare(String(b.createdAt ?? '')));
  const detections = [...(trace.detections ?? []), ...(trace.traceDetections ?? []), ...spans.flatMap((s) => s.detections ?? [])];
  const lines = [`neatlogs trace ${trace._id} "${trace.name ?? ''}": ${spans.length} spans${trace.hasError ? ', has errors' : ''}`];
  for (const d of detections.slice(0, 8)) lines.push(`neatlogs detection: ${clip(d, 300)}`);
  for (const s of spans.slice(0, maxSpans)) {
    const d = s.data ?? {};
    const bits = [
      `${s.node_type ?? ''} ${s.node_name ?? ''}`.trim(),
      s.status ? `status=${s.status}` : '',
      d.duration_ms ? `${d.duration_ms}ms` : '',
      d.tool_name && d.input_value ? `input=${clip(d.input_value, 120)}` : '',
      d.output_value ? `output=${clip(d.output_value, 160)}` : '',
      d.error_message ? `error=${d.error_type ?? ''}: ${clip(d.error_message, 160)}` : '',
    ];
    lines.push(`- ${bits.filter(Boolean).join(' ')}`);
  }
  return lines.join('\n');
}
// Entire Graph: a local, no-egress code graph (the `entire graph` plugin for the
// Entire CLI). Red uses it to measure each weak link's blast radius (who calls
// it, what co-changes with it), and Blue uses it to locate fix sites from the
// fault's hypothesis. Every call is best-effort: without the plugin, Bulwark
// falls back to its own static analysis.

import { spawnSync } from 'node:child_process';
import { homedir } from 'node:os';
import { join } from 'node:path';

const ENTIRE = process.env.ENTIRE_BIN || 'entire';
const PATH_WITH_LOCAL_BIN = `${join(homedir(), '.local', 'bin')}:${process.env.PATH ?? ''}`;

export interface GraphSymbol {
  name: string;
  kind: string;
  file: string;
  line?: number;
}

export interface BlastRadius {
  focus: GraphSymbol;
  /** Code that calls the weak link (doc and evidence mentions excluded). */
  callers: GraphSymbol[];
  callees: GraphSymbol[];
}

type Runner = (args: string[], cwd: string) => { status: number | null; stdout: string; stderr: string };

const defaultRunner: Runner = (args, cwd) => {
  const res = spawnSync(ENTIRE, ['graph', ...args], { cwd, encoding: 'utf8', timeout: 60_000, env: { ...process.env, PATH: PATH_WITH_LOCAL_BIN } });
  return { status: res.status, stdout: res.stdout ?? '', stderr: res.stderr ?? (res.error ? String(res.error) : '') };
};

const CODE_KINDS = new Set(['function', 'method', 'class', 'interface', 'type', 'variable', 'constant', 'property']);

function toSymbol(e: { name?: string; kind?: string; file_path?: string; start_line?: number }, line?: number): GraphSymbol {
  return { name: e.name ?? '?', kind: e.kind ?? '?', file: e.file_path ?? '?', line: line ?? e.start_line };
}

export class EntireGraph {
  constructor(
    private repo: string,
    private run: Runner = defaultRunner,
  ) {}

  available(): boolean {
    return this.run(['version'], this.repo).status === 0;
  }

  /** Blast radius of the symbol enclosing `file:line`, or null if the graph can't answer. */
  impact(file: string, line: number): BlastRadius | null {
    const res = this.run(['impact', '--symbol', `${file}:${line}`, '--repo', '.', '--format', 'json', '--exclude-tests', '--depth', '2'], this.repo);
    if (res.status !== 0) return null;
    try {
      const j = JSON.parse(res.stdout);
      if (!j.focus) return null;
      const pick = (section: { entries?: { endpoint: Record<string, unknown>; call_site?: { file_path?: string; line?: number } }[] } | undefined) =>
        (section?.entries ?? [])
          .filter((e) => CODE_KINDS.has(String(e.endpoint.kind)))
          .map((e) => toSymbol(e.endpoint as never, e.call_site?.line));
      return { focus: toSymbol(j.focus), callers: pick(j.callers), callees: pick(j.callees) };
    } catch {
      return null;
    }
  }

  /** Ranked fix-site candidates for a plain-language description, in Entire's compact agent format. */
  search(query: string, topK = 3): string | null {
    const res = this.run(['search', '--query', query, '--repo', '.', '--top-k', String(topK), '--format', 'agent', '--profile', 'full'], this.repo);
    return res.status === 0 && res.stdout.trim() ? res.stdout.trim() : null;
  }
}
import { AsyncLocalStorage } from 'node:async_hooks';
import { init, shutdown } from 'neatlogs';

// Traces go to neatlogs when NEATLOGS_API_KEY is set; otherwise spans are still
// created locally but not exported, so everything runs offline.
//
// A full Bulwark loop runs thousands of trials. Exporting every tool call of
// every trial would overflow the SDK's export queue (it silently drops spans
// past ~2k) and bury the phase traces that matter. So each experiment traces a
// sample of trials in full; the rest run inside `untraced()` and their spans are
// dropped by the mask below. Experiment-level results are always traced.
const quiet = new AsyncLocalStorage<boolean>();

export function untraced<T>(fn: () => Promise<T>): Promise<T> {
  return quiet.run(true, fn);
}

export async function initTracing(workflowName: string): Promise<boolean> {
  const exporting = Boolean(process.env.NEATLOGS_API_KEY);
  await init({
    apiKey: process.env.NEATLOGS_API_KEY,
    workflowName,
    tags: ['bulwark', 'neatHack'],
    disableExport: !exporting,
    ...(process.env.NEATLOGS_ENDPOINT ? { endpoint: process.env.NEATLOGS_ENDPOINT } : {}),
    batchSize: 512,
    mask: (span) => (quiet.getStore() ? null : span),
  });
  return exporting;
}

export const shutdownTracing = shutdown;
// Runs one sandboxed trial of the target agent under one fault, and records what
// actually happened: outcome, timing, steps, and the real side effects (refunds,
// emails) taken from the sandbox ledger rather than from the agent's own claims.

import { trace } from 'neatlogs';
import type { Brain } from '../targets/refundbot/agent';
import type { Email, Order, Refund } from '../targets/refundbot/payments';
import { injectFault, injectTicket, type Fault } from './chaos/faults';
import { TrialRecorder, type TrialEvent } from './recorder';
import { countTrial, recordLlmCall } from './cost/meter';
import { mulberry32 } from './stats';
import type { BrainMode, BulwarkTarget } from './target';
import { untraced } from './tracing';

export type Outcome = 'completed' | 'crashed' | 'hung' | 'runaway';
export type { BrainMode };

export interface TrialObservation {
  seed: number;
  outcome: Outcome;
  error?: string;
  durationMs: number;
  steps: number;
  faultsFired: number;
  reply?: string;
  customerEmail: string;
  orders: Order[];
  refunds: Refund[];
  emails: Email[];
  /** Ordered event timeline, only when the trial ran with `record: true`. */
  timeline?: TrialEvent[];
}

export interface TrialOptions {
  target: BulwarkTarget;
  fault?: Fault;
  seed: number;
  brain: BrainMode;
  /** Model override for LLM brains (default: the target's own choice). */
  model?: string;
  /** Wall-clock budget before the trial is declared hung. */
  deadlineMs: number;
  /** Safety net so a looping agent can't run forever; exceeding it is a "runaway". */
  maxSteps: number;
  /** Export this trial's spans to neatlogs. Experiments trace a sample; the rest run quietly. */
  traced?: boolean;
  /** Capture a step-by-step timeline for the replay viewer. Doesn't change results or randomness. */
  record?: boolean;
}

class StepCapExceeded extends Error {}

export async function runTrial(opts: TrialOptions): Promise<TrialObservation> {
  const fixtures = opts.target.fixtures();
  const { orders } = fixtures;
  const sandbox = opts.target.createSandbox(orders);
  const abort = new AbortController();
  const rec = opts.record ? new TrialRecorder() : undefined;
  const faultCtx = { rng: mulberry32(opts.seed), signal: abort.signal, fired: 0, onEvent: rec?.fault };
  // Social-engineering faults attack through the conversation: they rewrite the ticket, not the wire.
  const ticket = injectTicket(fixtures.ticket, opts.fault, faultCtx);
  const service = opts.target.createTransport(sandbox, abort.signal);
  const injected = injectFault(rec ? rec.serviceSide(service, sandbox) : service, opts.fault, faultCtx);
  const transport = rec ? rec.agentSide(injected) : injected;

  // Every LLM call the target makes is priced on the current run's cost meter.
  const inner: Brain = opts.target.createBrain(opts.brain, mulberry32(opts.seed ^ 0x9e3779b9), {
    model: opts.model,
    onUsage: (u) => recordLlmCall({ role: 'agent', ...u }),
  });
  countTrial();
  let steps = 0;
  const brain: Brain = {
    name: inner.name,
    decide: async (ctx) => {
      if (abort.signal.aborted) throw new Error('aborted');
      if (++steps > opts.maxSteps) throw new StepCapExceeded(`exceeded ${opts.maxSteps} steps`);
      if (!rec) return inner.decide(ctx);
      const decision = await inner.decide(ctx);
      rec.brain(steps, decision);
      return decision;
    },
  };

  const body = async (): Promise<TrialObservation> => {
    const start = performance.now();
    let outcome: Outcome = 'completed';
    let error: string | undefined;
    let reply: string | undefined;
    let timer: NodeJS.Timeout | undefined;
    const deadline = new Promise<'hung'>((resolve) => {
      timer = setTimeout(() => resolve('hung'), opts.deadlineMs);
    });

    const run = opts.target.run(ticket, { transport, brain });
    try {
      const res = await Promise.race([run, deadline]);
      if (res === 'hung') outcome = 'hung';
      else reply = res.reply;
    } catch (err) {
      outcome = err instanceof StepCapExceeded ? 'runaway' : 'crashed';
      error = err instanceof Error ? err.message : String(err);
    } finally {
      clearTimeout(timer);
      abort.abort();
    }

    const obs: TrialObservation = {
      seed: opts.seed,
      outcome,
      error,
      durationMs: performance.now() - start,
      steps: Math.min(steps, opts.maxSteps + 1),
      faultsFired: faultCtx.fired,
      reply,
      customerEmail: ticket.customerEmail,
      orders,
      refunds: [...sandbox.refunds],
      emails: [...sandbox.emails],
    };
    if (rec) {
      rec.outcome(obs);
      obs.timeline = rec.events;
    }

    // A hung run keeps going in the background until it notices the abort.
    // Let it wind down inside this trial, so none of its spans end after the
    // trial (and its trace) has closed.
    let grace: NodeJS.Timeout | undefined;
    await Promise.race([run.catch(() => {}), new Promise((r) => (grace = setTimeout(r, 1000)))]);
    clearTimeout(grace);
    rec?.stop();
    return obs;
  };

  if (opts.traced === false) return untraced(body);
  return trace(
    { name: 'bulwark.trial', kind: 'CHAIN', attributes: { target: opts.target.name, fault: opts.fault?.id ?? 'none', seed: opts.seed } },
    body,
  );
}

// Runs N trials per fault and turns them into an honest scorecard: pass rates
// with 95% confidence intervals, outcome breakdowns, and which rules broke.

import { trace } from 'neatlogs';
import type { Fault } from './chaos/faults';
import { runTrial, type BrainMode, type Outcome, type TrialObservation } from './harness';
import { compileRules } from './invariants';
import { dollarsAtRisk, money, riskCosts, type DollarsAtRisk } from './risk';
import { hashSeed, percentile, wilson } from './stats';
import type { BulwarkTarget } from './target';

export interface ExperimentResult {
