}

export async function runExperiment(
  target: BulwarkTarget,
  fault: Fault | undefined,
  opts: ExperimentOptions,
): Promise<ExperimentResult> {
  const faultId = fault?.id ?? 'baseline';
  const { compiled, uncompiled } = compileRules(target.rules);
  if (uncompiled.length) throw new Error(`could not compile rules: ${uncompiled.join(' | ')}`);

  return trace(
    {
      name: `experiment: ${faultId}`,
      kind: 'WORKFLOW',
      ...(opts.sessionId ? { sessionId: opts.sessionId, sessionFeatureName: 'bulwark-chaos' } : {}),
      attributes: { target: target.name, fault: faultId, trials: opts.trials, seed: opts.seed },
    },
    async () => {
      const outcomes: Record<Outcome, number> = { completed: 0, crashed: 0, hung: 0, runaway: 0 };
      const violations: Record<string, number> = Object.fromEntries(compiled.map((c) => [c.rule, 0]));
      const examples: ExperimentResult['examples'] = [];
      const perTrial: ExperimentResult['perTrial'] = [];
      let passed = 0;

      const observations: TrialObservation[] = await Promise.all(
        Array.from({ length: opts.trials }, async (_, i) => {
          const obs = await runTrial({
            target,
            fault,
            seed: hashSeed(opts.seed, faultId, i),
            brain: opts.brain,
            model: opts.model,
            deadlineMs: opts.deadlineMs,
            maxSteps: opts.maxSteps,
            traced: i < (opts.traceSample ?? Number(process.env.BULWARK_TRACE_SAMPLE ?? 2)),
          });
          outcomes[obs.outcome]++;
          const broken: BrokenRule[] = [];
          for (const { rule, check } of compiled) {
            const res = check(obs);
            if (res.ok) continue;
            broken.push({ rule, detail: res.detail });
            violations[rule]++;
            if (!examples.some((e) => e.rule === rule)) examples.push({ rule, seed: obs.seed, detail: res.detail });
          }
          if (broken.length === 0) passed++;
          perTrial[i] = { seed: obs.seed, outcome: obs.outcome, passed: broken.length === 0 };
          opts.onTrial?.({ index: i, obs, broken });
          return obs;
        }),
      );

      return {
        fault: faultId,
        title: fault?.title ?? 'No fault injected',
        hypothesis: fault?.hypothesis ?? 'The agent works when nothing breaks.',
        trials: opts.trials,
        passed,
        passRate: passed / opts.trials,
        ci95: wilson(passed, opts.trials),
        outcomes,
        violations,
        p95Ms: percentile(observations.map((o) => o.durationMs), 95),
        dollarsAtRisk: dollarsAtRisk(observations, riskCosts(target.risk)),
        examples,
        perTrial,
      };
    },
  );
}

const pct = (x: number) => `${Math.round(x * 100)}%`;

/** Per-1k figure plus what it's made of, e.g. "$1,234 (over-refund $980, 3 lost, 2 escalated of 20)". Over-refund is also per 1k. */
export function riskCell(r: ExperimentResult): string {
  const d = r.dollarsAtRisk;
  if (!d) return '—';
  if (d.totalUsd === 0) return '$0';
  const parts = [
    d.overRefundUsd ? `over-refund ${money((d.overRefundUsd / d.trials) * 1000)}` : '',
    d.lostTickets ? `${d.lostTickets} lost` : '',
    d.escalations ? `${d.escalations} escalated` : '',
  ].filter(Boolean);
  return `${money(d.per1kTickets)} (${parts.join(', ')}${d.lostTickets || d.escalations ? ` of ${d.trials}` : ''})`;
}

export function renderMarkdown(target: BulwarkTarget, results: ExperimentResult[], meta: Record<string, unknown>): string {
  const lines = [
    `# Bulwark scorecard: ${target.name}`,
    '',
    Object.entries(meta)
      .map(([k, v]) => `**${k}**: ${v}`)
      .join(' · '),
    '',
    '| Fault | Pass | 95% CI | Crashed | Hung | Runaway | p95 | $ at risk / 1k tickets | Broken rules |',
    '|---|---|---|---|---|---|---|---|---|',
  ];
  for (const r of results) {
    const broken = Object.entries(r.violations)
      .filter(([, n]) => n > 0)
      .map(([rule, n]) => `${rule} (${n})`)
      .join('<br>');
    lines.push(
      `| ${r.fault} | ${r.passed}/${r.trials} | ${pct(r.ci95[0])}–${pct(r.ci95[1])} | ${r.outcomes.crashed} | ${r.outcomes.hung} | ${r.outcomes.runaway} | ${Math.round(r.p95Ms)}ms | ${riskCell(r)} | ${broken || '—'} |`,
    );
  }
  const costs = results[0]?.dollarsAtRisk?.costs;
  if (costs) {
    lines.push(
      '',
      `_$ at risk = over-refunds read from the payments ledger (measured) + $${costs.lostTicketUsd} per ticket left without a reply + $${costs.escalationUsd} per crashed/hung run needing a human (assumptions, set on the target)._`,
    );
  }
  lines.push('', '## Hypotheses and replayable failures', '');
  for (const r of results) {
    lines.push(`- **${r.fault}**: ${r.hypothesis}`);
    for (const e of r.examples) lines.push(`  - ✗ ${e.rule} → ${e.detail ?? ''} (seed ${e.seed})`);
  }
  return lines.join('\n') + '\n';
}

export function renderConsole(results: ExperimentResult[]): string {
  const rows = results.map((r) => {
    const broken = Object.entries(r.violations)
      .filter(([, n]) => n > 0)
      .map(([rule, n]) => `${n}× ${rule}`)
      .join('; ');
    return [
      r.fault.padEnd(22),
      `${r.passed}/${r.trials}`.padStart(6),
      `${pct(r.ci95[0])}–${pct(r.ci95[1])}`.padEnd(10),
      `crash ${r.outcomes.crashed} hung ${r.outcomes.hung} runaway ${r.outcomes.runaway}`.padEnd(28),
      (r.dollarsAtRisk ? money(r.dollarsAtRisk.per1kTickets) : '—').padStart(9),
      broken || 'all rules held',
    ].join('  ');
  });
  return [`${'fault'.padEnd(22)}  ${'pass'.padStart(6)}  ${'95% CI'.padEnd(10)}  ${'outcomes'.padEnd(28)}  ${'$risk/1k'.padStart(9)}  broken rules`, ...rows].join('\n');
}
// Red agent, step 1: read the target's source and find the weak links, i.e. tool
// calls that can't survive the faults in the catalog. Each finding names the
// file, line and the fault that should trigger it, so every attack starts from
// a hypothesis grounded in the code rather than a random guess.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { FAULTS, type FaultKind } from '../chaos/faults';
import type { Provenance } from '../provenance/entire';
import type { BulwarkTarget } from '../target';

export interface Finding {
  kind: FaultKind;
  severity: 'high' | 'medium';
  file: string;
  line: number;
  tool?: string;
  why: string;
  faults: string[];
  /** Who introduced this line: commit, and the Entire session/prompt when known (bulwark/provenance). */
  provenance?: Provenance;
}

const WRITE_ENDPOINT = /\.(create|send)$/;

function lineOf(src: string, index: number): number {
  return src.slice(0, index).split('\n').length;
}

function faultsFor(kind: FaultKind, endpoint?: string): string[] {
  return FAULTS.filter((f) => f.kind === kind && (!endpoint || f.endpoint === endpoint)).map((f) => f.id);
}

export function analyzeTarget(dir: string, target: BulwarkTarget): Finding[] {
  const findings: Finding[] = [];

  for (const file of target.editableFiles) {
    const src = readFileSync(join(dir, file), 'utf8');

    // Tool definitions: span({ kind: 'TOOL', name: '<tool>' ... }) up to the next tool.
    const toolStarts = [...src.matchAll(/span\(\{ kind: 'TOOL', name: '(\w+)'/g)];
    toolStarts.forEach((m, i) => {
      const start = m.index!;
      const body = src.slice(start, toolStarts[i + 1]?.index ?? src.length);
      const tool = m[1];
      const calls = [...body.matchAll(/transport\('([\w.]+)'/g)];
      if (calls.length === 0) return;
      // The tool's primary call is the one that writes, if any; otherwise its first call.
      const primary = calls.find((c) => WRITE_ENDPOINT.test(c[1])) ?? calls[0];
      const endpoint = primary[1];
      const line = lineOf(src, start + primary.index!);
      const writes = WRITE_ENDPOINT.test(endpoint);
      const add = (kind: FaultKind, severity: Finding['severity'], why: string) => {
        const faults = faultsFor(kind, endpoint);
        if (faults.length) findings.push({ kind, severity, file, line, tool, why, faults });
      };

      if (!/withTimeout\(/.test(body)) add('latency', 'medium', `${tool} calls ${endpoint} with no timeout`);
      if (!/withRetry\(/.test(body)) add('rate-limit', 'medium', `${tool} never retries ${endpoint} on transient errors`);
      if (/JSON\.parse\(/.test(body) && !/validate|parse[A-Z]\w*\(/.test(body)) {
        add('malformed', 'medium', `${tool} trusts the JSON from ${endpoint} without validating it`);
      }
      if (writes && /withRetry\(/.test(body) && !/idempotencyKey/.test(body)) {
        add('commit-timeout', 'high', `${tool} retries a money-moving call (${endpoint}) without an idempotency key`);
      }
      if (/\)\.text\)?;/.test(body) && !/sanitize/i.test(body)) {
        add('injection', 'high', `${tool} passes raw text from ${endpoint} to the model, so injected instructions reach it`);
      }
      if (writes && /amount/.test(body) && !/order\.total/.test(body)) {
        for (const f of faultsFor('injection')) {
          findings.push({
            kind: 'injection',
            severity: 'high',
            file,
            line,
            tool,
            why: `${tool} moves money without checking the amount against the order total`,
            faults: [f],
          });
        }
      }
      // Social engineering arrives in the ticket, so the fault isn't tied to this endpoint.
      if (writes && /amount/.test(body) && !/customerEmail/.test(body)) {
        const faults = faultsFor('social');
        if (faults.length) {
          findings.push({
            kind: 'social',
            severity: 'high',
            file,
            line,
            tool,
            why: `${tool} moves money without checking that the order belongs to the ticket's customer, so a persuasive customer can redirect it`,
            faults,
          });
        }
      }
    });

    const loop = src.match(/while \(true\)/);
    if (loop && !/MAX_STEPS/.test(src)) {
      findings.push({
        kind: 'loop',
        severity: 'medium',
        file,
        line: lineOf(src, loop.index!),
        why: 'the agent loop has no step budget, so a stuck tool means unbounded steps and cost',
        faults: faultsFor('loop'),
      });
    }
  }

  return findings.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'high' ? -1 : 1));
}
// npm run fix -- [--fault <id>|all] [--fixer auto|playbook|claude] [--red-trials 20]
//                [--judge-trials 40] [--seed 42] [--max-attempts 4] [--no-memory] [--apply] [--pr] [--generated]
//                [--slo 0.99[,<fault>=0.999]] [--slo-confidence 0.95] [--max-slo-trials 1000]
//                [--max-latency-overhead 50%] [--max-step-overhead 2] [--max-cost-overhead 20%] [--overhead-policy reject|flag]
//                [--tournament claude-sonnet-5,deepseek-v4-flash | playbook,playbook-strong]
//
// The full loop: attack, fix, verify, prove. Writes artifacts to .bulwark/runs/<id>/.

import './env';
import { parseArgs } from 'node:util';
import { usd } from './cost/meter';
import { registerFaults } from './chaos/faults';
import { loadGeneratedFaults } from './red/generate';
import { fixedWithOverhead } from './judge/judge';
import { describeOverhead, parsePercent, type OverheadBudgets } from './judge/overhead';
import { DEFAULT_MAX_SLO_TRIALS, DEFAULT_SLO_CONFIDENCE, describePlan, fmtRate, parseSlo } from './judge/slo';
import { parseTournament } from './judge/tournament';
import { applyAsBranch, DEFAULT_LOOP, openPullRequest, runLoop, type LoopEvent } from './loop/orchestrator';
import { summarizeProvenance } from './provenance/entire';
import { money } from './risk';
import { initTracing, shutdownTracing } from './tracing';

const c = {
  dim: (s: string) => `\x1b[2m${s}\x1b[0m`,
  red: (s: string) => `\x1b[31m${s}\x1b[0m`,
  green: (s: string) => `\x1b[32m${s}\x1b[0m`,
  yellow: (s: string) => `\x1b[33m${s}\x1b[0m`,
  blue: (s: string) => `\x1b[34m${s}\x1b[0m`,
  bold: (s: string) => `\x1b[1m${s}\x1b[0m`,
};
const pct = (x: number) => `${Math.round(x * 100)}%`;

let allPassAfter = true;

function print(e: LoopEvent) {
  switch (e.type) {
    case 'run-start':
      return console.log(c.bold(`Bulwark loop → ${e.target}`) + c.dim(` | fixer ${e.fixer} | red ${e.redTrials} trials, judge ${e.judgeTrials} trials | run ${e.runId}\n`));
    case 'analyze':
      console.log(c.red('RED') + ` found ${e.findings.length} weak links:`);
      for (const f of e.findings) console.log(`  ${f.severity === 'high' ? c.red('high') : c.yellow('med ')}  ${f.file}:${f.line}  ${f.why}`);
      for (const line of summarizeProvenance(e.provenance ?? [])) console.log(c.dim(`  provenance: ${line}`));
      return console.log();
    case 'scorecard': {
      if (e.phase === 'after') allPassAfter = e.results.every((r) => r.passed === r.trials);
      const label = e.phase === 'before' ? c.red('RED') + ' scorecard (before)' : c.bold('Scorecard after fixes');
      console.log(`${label}: overall ${pct(e.overall)} of trials kept every rule`);
      for (const r of e.results) {
        const risk = r.dollarsAtRisk ? c.dim(`  ${money(r.dollarsAtRisk.per1kTickets)} at risk / 1k tickets`) : '';
        console.log(`  ${r.fault.padEnd(22)} ${(r.passed === r.trials ? c.green : c.red)(`${r.passed}/${r.trials}`.padEnd(6))}${risk}`);
      }
      return console.log();
    }
    case 'fault-start':
      return console.log(c.bold(`▶ ${e.fault}`) + c.dim(`  ${e.hypothesis}`));
    case 'fault-skip':
      return console.log(c.dim(`  skipped: ${e.reason}`));
    case 'checkpoint':
      return console.log(c.dim(`  ${e.action === 'save' ? '⎘ checkpoint' : '↺ rolled back to'} ${e.id}`));
    case 'slo-plan':
      console.log(c.bold(`SLO plan`) + c.dim(` (${fmtRate(e.confidence)} confidence, ${e.method})`));
      for (const p of e.plans) console.log(`  ${describePlan(p)}`);
      return console.log();
    case 'attempt':
      return console.log(`  ${c.blue('BLUE')} ${e.round ? `round ${e.round} candidate` : 'attempt'} ${e.n}: ${e.title} ${c.dim(`(${e.strategy}, ${e.author}, +${e.added}/-${e.removed})`)}`);
    case 'verdict': {
      const tag =
        e.status === 'fixed' ? (fixedWithOverhead(e) ? c.yellow('FIXED WITH OVERHEAD') : c.green('FIXED')) : e.status === 'inconclusive' ? c.yellow('INCONCLUSIVE') : c.red('REJECTED');
      console.log(`  ${c.yellow('JUDGE')} ${tag} ${e.reasons.join('; ')}`);
      if (e.overhead) console.log(c.dim(`        overhead: ${describeOverhead(e.overhead)}`));
      return;
    }
    case 'tournament': {
      console.log(`  ${c.bold('TOURNAMENT')} round ${e.round}: ${e.winner ? c.green(`${e.winner} wins`) : c.red('no winner')}`);
      for (const r of e.ranking) console.log(`    ${r.rank}. ${r.entrant.padEnd(18)} ${(r.strategy ?? '—').padEnd(26)} ${r.outcome === 'winner' ? c.green(r.outcome) : c.dim(r.outcome)}: ${r.reason}`);
      return;
    }
    case 'mutation':
      return console.log(`  ${c.dim('GUARD')} regression test without fix ${e.unfixedPassed}/${e.trials}, with fix ${e.fixedPassed}/${e.trials} ${e.ok ? c.green('✓ proven') : c.red('✗ not proven')}`);
    case 'fault-done':
      return console.log();
    case 'residual':
      if (e.findings.length === 0) return console.log(c.green('No weak links remain in the final code.\n'));
      console.log(c.yellow(`Remaining risk (${e.findings.length}):`) + (allPassAfter ? ' every attack passes, but the analyzer still sees:' : ' the analyzer still sees:'));
      for (const f of e.findings) console.log(`  ${f.file}:${f.line}  ${f.why}`);
      return console.log();
    case 'log':
      return console.log(c.dim(`  ${e.message}`));
    case 'run-done': {
      const s = e.summary;
      console.log(c.bold(`Resilience ${pct(s.overallBefore)} → ${pct(s.overallAfter)}`) + `  fixed ${s.fixed.length}, unfixed ${s.unfixed.length}, skipped ${s.skipped.length} · ${s.attempts} attempts, ${s.rollbacks} rollbacks`);
      if (s.cost) {
        const k = s.cost;
        console.log(`Run cost ${c.bold(usd(k.totalUsd))}` + c.dim(` = LLM ${usd(k.llmUsd)} (${k.calls} calls, ${k.inputTokens + k.outputTokens} tokens) + compute ${usd(k.computeUsd)} (${Math.round(k.wallMs / 1000)}s) · ${k.trials} trials`));
      }
      return console.log(c.dim(`Artifacts: ${s.dir}/ (fix.patch, PR.md, postmortem-*.md, badge.svg, summary.json)`));
    }
  }
}

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'all' },
      fixer: { type: 'string', default: DEFAULT_LOOP.fixer },
      'red-trials': { type: 'string', default: String(DEFAULT_LOOP.redTrials) },
      'judge-trials': { type: 'string', default: String(DEFAULT_LOOP.judgeTrials) },
      seed: { type: 'string', default: String(DEFAULT_LOOP.seed) },
      'max-attempts': { type: 'string', default: String(DEFAULT_LOOP.maxAttempts) },
      'no-memory': { type: 'boolean', default: false },
      apply: { type: 'boolean', default: false },
      pr: { type: 'boolean', default: false },
      target: { type: 'string', default: 'targets/refundbot' },
      generated: { type: 'boolean', default: false },
      slo: { type: 'string' },
      'slo-confidence': { type: 'string', default: String(DEFAULT_SLO_CONFIDENCE) },
      'max-slo-trials': { type: 'string', default: String(DEFAULT_MAX_SLO_TRIALS) },
      'max-latency-overhead': { type: 'string' },
      'max-step-overhead': { type: 'string' },
      'max-cost-overhead': { type: 'string' },
      'overhead-policy': { type: 'string', default: 'reject' },
      tournament: { type: 'string' },
    },
  });
  // Generative Red's accepted faults join the catalog, so Red, Blue, Judge and Guard all see them.
  if (values.generated) registerFaults(loadGeneratedFaults());
  const slo = values.slo ? parseSlo(values.slo, Number(values['slo-confidence']), Number(values['max-slo-trials'])) : undefined;
  const policy = values['overhead-policy'] as 'reject' | 'flag';
  if (!['reject', 'flag'].includes(policy)) throw new Error('--overhead-policy must be reject or flag');
  const budgets: OverheadBudgets = {
    policy,
    ...(values['max-latency-overhead'] ? { maxLatencyOverhead: parsePercent(values['max-latency-overhead']) } : {}),
    ...(values['max-step-overhead'] ? { maxStepOverhead: Number(values['max-step-overhead']) } : {}),
    ...(values['max-cost-overhead'] ? { maxCostOverhead: parsePercent(values['max-cost-overhead']) } : {}),
  };
  if (budgets.maxStepOverhead !== undefined && !(budgets.maxStepOverhead >= 0)) throw new Error('--max-step-overhead must be a number of steps, e.g. 2');
  const tournament = values.tournament ? parseTournament(values.tournament) : undefined;
  const fixer = values.fixer as 'auto' | 'playbook' | 'claude';
  if (!['auto', 'playbook', 'claude'].includes(fixer)) throw new Error('--fixer must be auto, playbook or claude');

  await initTracing('bulwark-loop');
  const summary = await runLoop(
    {
      targetDir: values.target!,
      faults: values.fault === 'all' ? 'all' : values.fault!.split(','),
      fixer,
      redTrials: Number(values['red-trials']),
      judgeTrials: Number(values['judge-trials']),
      seed: Number(values.seed),
      maxAttempts: Number(values['max-attempts']),
      memory: !values['no-memory'],
      slo,
      budgets,
      tournament,
    },
    print,
  );

  if ((values.apply || values.pr) && summary.fixed.length) {
    const branch = applyAsBranch(summary);
    console.log(c.green(`Committed verified fixes to branch ${branch}`));
    if (values.pr) console.log(c.green(`Opened ${openPullRequest(branch, summary)}`));
  }
  await shutdownTracing();
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
