// Human-facing artifacts from a Bulwark run: a postmortem per fault, the PR
// description, and a resilience badge.

import { usd, type CostSummary } from '../cost/meter';
import type { MutationCheck } from '../guard';
import type { Verdict } from '../judge/judge';
import { describeProvenance, summarizeProvenance, type Provenance } from '../provenance/entire';
import { describeOverhead } from '../judge/overhead';
import { describeSlo } from '../judge/slo';
import type { TournamentResult } from '../judge/tournament';
import type { Finding } from '../red/analyze';
import { combineRisk, money } from '../risk';
import type { ExperimentResult } from '../scorecard';

export interface AttemptRecord {
  n: number;
  strategy: string;
  title: string;
  rationale: string;
  author: string;
  diff: string;
  checkpoint: string;
  verdict: Pick<Verdict, 'status' | 'reasons' | 'pValue' | 'slo' | 'overhead'> & { afterPassed: number; trials: number };
  /** Set when this attempt was one candidate in a fix tournament. */
  tournament?: { round: number; rank: number; outcome: 'winner' | 'loser' | 'no-winner'; reason: string };
}

/** The attempt that was applied: verdict fixed, and not a tournament loser. */
export const appliedAttempt = (rec: Pick<FaultRecord, 'attempts'>) =>
  rec.attempts.find((a) => a.verdict.status === 'fixed' && a.tournament?.outcome !== 'loser');

export interface FaultRecord {
  fault: string;
  title: string;
  hypothesis: string;
  status: 'fixed' | 'unfixed' | 'skipped';
  skipReason?: string;
  findings: Finding[];
  before?: ExperimentResult;
  attempts: AttemptRecord[];
  mutation?: Pick<MutationCheck, 'ok'> & { unfixedPassed: number; fixedPassed: number; trials: number };
  /** One entry per tournament round, when --tournament was used. */
  tournament?: TournamentResult[];
}

const pct = (x: number) => `${Math.round(x * 100)}%`;
const brokenRules = (r: ExperimentResult) =>
  Object.entries(r.violations)
    .filter(([, n]) => n > 0)
    .map(([rule, n]) => `${n}× ${rule}`)
    .join('; ') || 'none';

export function postmortem(rec: FaultRecord, runId: string): string {
  const winner = appliedAttempt(rec);
  const lines = [
    `# Postmortem: ${rec.fault}`,
    '',
    `**Run** ${runId} · **Status** ${rec.status === 'fixed' ? '✅ fixed and verified' : rec.status === 'skipped' ? `⏭ skipped (${rec.skipReason})` : '❌ not fixed'}`,
    '',
    '## Hypothesis',
    rec.hypothesis,
    '',
  ];
  if (rec.before) {
    lines.push(
      '## Blast radius (before)',
      `${rec.before.passed}/${rec.before.trials} trials passed (95% CI ${pct(rec.before.ci95[0])}–${pct(rec.before.ci95[1])}).`,
      `Outcomes: ${Object.entries(rec.before.outcomes).filter(([, n]) => n).map(([k, n]) => `${n} ${k}`).join(', ')}. Broken rules: ${brokenRules(rec.before).replace(/\.$/, '')}.`,
      ...rec.before.examples.map((e) => `- Replay: seed ${e.seed} → ${e.rule} (${e.detail ?? ''})`),
      '',
    );
  }
  if (rec.findings.length) {
    lines.push(
      '## Weak links found in the code',
      ...rec.findings.map((f) => `- \`${f.file}:${f.line}\` ${f.why}${f.provenance ? `\n  - Provenance: ${describeProvenance(f.provenance)}` : ''}`),
      '',
    );
  }
  if (rec.attempts.length) {
    lines.push('## Attempts', '');
    for (const a of rec.attempts) {
      const icon = a.verdict.status === 'fixed' ? '✅' : a.verdict.status === 'inconclusive' ? '❔' : '❌';
      lines.push(
        `### ${icon} Attempt ${a.n}: ${a.title} (\`${a.strategy}\`, by ${a.author}${a.tournament ? `, tournament round ${a.tournament.round}` : ''})`,
        a.rationale,
        '',
        `Checkpoint before attempt: \`${a.checkpoint}\`. Judge: **${a.verdict.status}**. ${a.verdict.reasons.join('; ')}.`,
        ...(a.verdict.overhead ? [`Overhead: ${describeOverhead(a.verdict.overhead)}.`] : []),
        a.tournament
          ? a.tournament.outcome === 'winner'
            ? `🏆 Tournament winner: ${a.tournament.reason}.`
            : `Not applied (rank ${a.tournament.rank}): ${a.tournament.reason}.`
          : a.verdict.status === 'fixed'
            ? ''
            : `Rolled back to \`${a.checkpoint}\`.`,
        '',
      );
    }
  }
  if (rec.tournament?.length) {
    lines.push('## Fix tournament', '');
    for (const t of rec.tournament) {
      lines.push(
        `Round ${t.round}: ${t.entrants.join(' vs ')} → ${t.winner ? `**${t.winner}** wins` : 'no winner, all candidates rolled back'}`,
        '',
        '| Rank | Entrant | Strategy | Verdict | SLO | Happy-path overhead | Diff | Outcome |',
        '|---|---|---|---|---|---|---|---|',
        ...t.ranking.map(
          (c) =>
            `| ${c.rank} | ${c.entrant} | ${c.strategy ?? '—'} | ${c.status} | ${c.sloDemonstrated === undefined ? '—' : c.sloDemonstrated ? 'demonstrated' : 'not demonstrated'} | ${c.overhead ? `steps ${c.overhead.after.avgSteps.toFixed(1)}, p50 ${Math.round(c.overhead.after.p50Ms)}ms${c.overhead.after.costPerRunUsd !== undefined ? `, $${c.overhead.after.costPerRunUsd.toFixed(4)}/run` : ''}` : '—'} | ${c.diffSize} | ${c.outcome}: ${c.reason} |`,
        ),
        '',
      );
    }
  }
  if (winner) {
    lines.push('## Root cause and fix', winner.rationale, '', '```diff', winner.diff.trimEnd(), '```', '');
    if (winner.verdict.slo) lines.push('## Reliability target', `${describeSlo(winner.verdict.slo)}. Method: ${winner.verdict.slo.method}.`, '');
    if (winner.verdict.overhead) {
      const o = winner.verdict.overhead;
      lines.push(
        '## Overhead',
        `Compared with the unpatched code on the no-fault baseline (${o.after.runs} runs): ${describeOverhead(o)}.`,
        ...(o.underFault ? [`Under ${rec.fault} (informational, not budgeted): p50 ${Math.round(o.underFault.before.p50Ms)}→${Math.round(o.underFault.after.p50Ms)}ms, avg steps ${o.underFault.before.avgSteps.toFixed(1)}→${o.underFault.after.avgSteps.toFixed(1)}.`] : []),
        o.withinBudget ? '' : `⚠️ Fixed with overhead: ${o.exceeded.join('; ')}.`,
        '',
      );
    }
  }
  if (rec.mutation) {
    const m = rec.mutation;
    lines.push(
      '## Proof the regression test guards the fix',
      `With the fix removed: ${m.unfixedPassed}/${m.trials} passed. With the fix: ${m.fixedPassed}/${m.trials} passed. ${m.ok ? '✅ The test catches the bug.' : '❌ The test does not distinguish fixed from unfixed code.'}`,
      '',
    );
  }
  return lines.join('\n');
}

export function prBody(args: {
  target: string;
  runId: string;
  records: FaultRecord[];
  before: Record<string, ExperimentResult>;
  after: Record<string, ExperimentResult>;
  diff: string;
  traces: string;
  residual: Finding[];
  /** Where the weak links came from (bulwark/provenance). */
  provenance?: Provenance[];
  cost?: CostSummary;
}): string {
  const fixed = args.records.filter((r) => r.status === 'fixed');
  const risk1k = (r?: ExperimentResult) => (r?.dollarsAtRisk ? money(r.dollarsAtRisk.per1kTickets) : '—');
  const rows = Object.keys(args.before).map((id) => {
    const b = args.before[id];
    const a = args.after[id];
    return `| ${id} | ${b.passed}/${b.trials} | ${a.passed}/${a.trials} | ${pct(a.ci95[0])}–${pct(a.ci95[1])} | ${risk1k(b)} → ${risk1k(a)} |`;
  });
  const risk = riskSummary(args.before, args.after);
  return [
    `## Bulwark: resilience fixes for ${args.target}`,
    '',
    `Bulwark attacked \`${args.target}\` with ${Object.keys(args.before).length - 1} faults, fixed ${fixed.length}, and verified each fix on fresh seeds with an independent Judge.`,
    '',
    '| Fault | Before | After | After 95% CI | $ at risk / 1k tickets |',
    '|---|---|---|---|---|',
    ...rows,
    '',
    ...(risk ? [risk, ''] : []),
    '### Fixes',
    ...fixed.map((r) => {
      const w = appliedAttempt(r)!;
      const tries = r.tournament?.length
        ? ` (tournament: ${w.author} beat ${r.tournament.at(-1)!.ranking.filter((c) => c.outcome === 'loser').map((c) => `${c.entrant}, ${c.reason}`).join('; ') || 'no other entrant'})`
        : r.attempts.length > 1
          ? ` (attempt ${w.n}; ${r.attempts.length - 1} rejected and rolled back first)`
          : '';
      const overhead = w.verdict.overhead ? ` Overhead: ${describeOverhead(w.verdict.overhead)}${w.verdict.overhead.withinBudget ? '' : ` ⚠️ fixed with overhead (${w.verdict.overhead.exceeded.join('; ')})`}.` : '';
      return `- **${r.fault}**: ${w.title}${tries}. ${w.verdict.reasons.join('; ')}.${overhead}`;
    }),
    ...args.records.filter((r) => r.status === 'skipped').map((r) => `- **${r.fault}**: no change needed (${r.skipReason})`),
    '',
    ...sloSection(args.records),
    '### Remaining risk',
    ...(args.residual.length
      ? args.residual.map((f) => `- \`${f.file}:${f.line}\` ${f.why}. Every attack now passes, but the weak link is still in the code.`)
      : ['- The analyzer finds no remaining weak links.']),
    '',
    ...(args.provenance?.length ? ['### Provenance', ...summarizeProvenance(args.provenance).map((l) => `- ${l}`), ''] : []),
    '### Evidence',
    '- Each fix ships a chaos regression test in `chaos-tests/`, proven to fail without the fix and pass with it.',
    `- Postmortems: \`.bulwark/runs/${args.runId}/postmortem-*.md\``,
    `- Traces: ${args.traces}`,
    ...(args.cost
      ? [`- Run cost: ${usd(args.cost.totalUsd)} (LLM ${usd(args.cost.llmUsd)} over ${args.cost.calls} calls, compute ${usd(args.cost.computeUsd)} for ${Math.round(args.cost.wallMs / 1000)}s; ${args.cost.trials} trials)`]
      : []),
    '',
    '<details><summary>Full diff</summary>',
    '',
    '```diff',
    args.diff.trimEnd(),
    '```',
    '</details>',
    '',
    '_A human reviews and merges. Bulwark never pushes to main._',
    '',
  ].join('\n');
}

function sloSection(records: FaultRecord[]): string[] {
  const rows = records.flatMap((r) => {
    const a = appliedAttempt(r) ?? r.attempts.at(-1);
    return a?.verdict.slo ? [`- **${r.fault}**: ${describeSlo(a.verdict.slo)}.`] : [];
  });
  if (!rows.length) return [];
  const method = records.flatMap((r) => r.attempts).find((a) => a.verdict.slo)!.verdict.slo!.method;
  return ['### Reliability targets (SLO)', ...rows, `_Method: ${method}. "Demonstrated" means every planned trial passed; nothing stronger is claimed._`, ''];
}

/** One line: what every attack in the suite would cost per 1,000 tickets, before vs after. */
export function riskSummary(before: Record<string, ExperimentResult>, after: Record<string, ExperimentResult>): string | undefined {
  const pick = (rs: Record<string, ExperimentResult>) =>
    Object.values(rs)
      .filter((r) => r.fault !== 'baseline' && r.dollarsAtRisk)
      .map((r) => r.dollarsAtRisk);
  const b = pick(before);
  const a = pick(after);
  if (!b.length || !a.length) return undefined;
  const cb = combineRisk(b);
  const ca = combineRisk(a);
  return (
    `**Dollars at risk** across the attack suite: ${money(cb.per1kTickets)} → ${money(ca.per1kTickets)} per 1,000 tickets. ` +
    `Over-refunds come from the payments ledger; each ticket left without a reply is priced at $${cb.costs.lostTicketUsd} and each crashed/hung run at $${cb.costs.escalationUsd} (assumptions set on the target).`
  );
}

export function badgeSvg(passRate: number): string {
  const label = 'resilience';
  const value = `${Math.round(passRate * 100)}%`;
  const color = passRate >= 0.95 ? '#1f9d55' : passRate >= 0.8 ? '#d97706' : '#dc2626';
  const lw = 74;
  const vw = 46;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${lw + vw}" height="20" role="img" aria-label="${label}: ${value}">
<linearGradient id="s" x2="0" y2="100%"><stop offset="0" stop-color="#bbb" stop-opacity=".1"/><stop offset="1" stop-opacity=".1"/></linearGradient>
<clipPath id="r"><rect width="${lw + vw}" height="20" rx="3" fill="#fff"/></clipPath>
<g clip-path="url(#r)"><rect width="${lw}" height="20" fill="#555"/><rect x="${lw}" width="${vw}" height="20" fill="${color}"/><rect width="${lw + vw}" height="20" fill="url(#s)"/></g>
<g fill="#fff" text-anchor="middle" font-family="Verdana,Geneva,DejaVu Sans,sans-serif" font-size="11">
<text x="${lw / 2}" y="14">${label}</text><text x="${lw + vw / 2}" y="14">${value}</text></g>
</svg>
`;
}

/** Overall resilience: share of trials across every fault that kept every rule. */
export function overallPassRate(results: Record<string, ExperimentResult>): number {
  const all = Object.values(results);
  const trials = all.reduce((s, r) => s + r.trials, 0);
  return trials ? all.reduce((s, r) => s + r.passed, 0) / trials : 0;
}
# How Bulwark uses Entire

Bulwark uses [Entire](https://docs.entire.io/overview) in two ways:

1. **While we build Bulwark.** Entire is enabled on this repo for Claude Code. Each commit made during an agent session gets an `Entire-Checkpoint: <id>` trailer, and the session (prompt, transcript, subagent transcripts, token usage) is stored as a git ref `refs/entire/checkpoints/<shard>/<id>`.
2. **Inside Bulwark's reports (feature #22, bug provenance).** Red's analyzer finds weak links at a file and line. Bulwark traces each line back to the commit that introduced it, and through Entire to the AI coding session, prompt and checkpoint behind that commit. The result is shown in the postmortem, the PR body, the CLI output and the live `analyze` event.

## Verify it yourself

Run these from the repo root. Entire CLI 0.11.4 is installed at `~/.local/bin/entire`.

```bash
entire status                          # enabled, agent "Claude Code", active session
entire status --json
entire checkpoint list                 # checkpoints on this branch (imported history + new ones)
git for-each-ref refs/entire/          # the checkpoint refs themselves
git log --format='%h %s%n  %(trailers:key=Entire-Checkpoint)' | head -20   # which commits carry a trailer

entire why docs/FEATURES.md:63 --json            # a line written in a checkpointed session
entire checkpoint explain 01M4MGGKEQXJR07RTC3SAJQ3P8 --short

npm run provenance -- targets/refundbot/tools.ts:87   # Bulwark's provenance for one line
npm run provenance -- --target targets/refundbot      # ...for every weak link Red finds
npm run provenance -- targets/refundbot/tools.ts:87 --json
npm run fix -- --fixer playbook                       # provenance appears under RED and in .bulwark/runs/<id>/PR.md
```

Checkpoint refs are local unless pushed (`checkpoint_push_disabled` is true in `entire status --json`). A fresh clone of the GitHub repo has the `Entire-Checkpoint:` trailers in its commit messages but not the session data. Run `git fetch origin 'refs/entire/*:refs/entire/*'` after the refs are pushed.

## How provenance is resolved

`bulwark/provenance/entire.ts` takes a repo-relative `file:line` and tries each source in order, using the best evidence it finds:

| Step | Source | What it gives |
|---|---|---|
| 1 | `entire why <file>:<line> --json` | Entire's own line attribution. When the blamed commit has a checkpoint: checkpoint, session, agent, model and prompt. |
| 2 | `git blame --porcelain` → the commit's `Entire-Checkpoint:` trailer → `refs/entire/checkpoints/<id[-2:]>/<id>`:`0/metadata.json` and `0/prompt.txt` | The same answer without the Entire CLI. |
| 2b | the checkpoint's `tasks/<id>/agent-*.jsonl` and `task.json` | When the checkpoint has no prompt because subagents did the work: the subagent task whose transcript wrote this exact line. |
| 3 | Transcript match in imported sessions | For commits made before Entire's hooks were installed. If a session that Entire imported has a `Write`/`Edit` tool call that put this exact line (compared trimmed) into this file after the parent commit and before this commit, Bulwark names that session and the prompt of the checkpoint whose transcript holds the write. This is labelled `match: transcript`. |
| 4 | Plain `git blame` | Commit, author, date and subject, plus the reason no session was linked. |

Every step degrades without crashing. If Entire isn't installed, the repo has no checkpoints, the line is uncommitted, or the file is outside git, the record says so in `note`, and the loop carries on. Set `BULWARK_PROVENANCE=0` to skip provenance entirely.

Each `Provenance` record has: `source` (`entire` | `git` | `unavailable`), `match` (`checkpoint` | `transcript`), `commit`, `author`, `date`, `subject`, `checkpointId`, `sessionId`, `agent`, `model`, `prompt`, `task`, `writtenAt` and `note`.

## What is real today (checked Oct 11 2026)

- **Commits before `e44db55` have no checkpoint trailer.** Entire was enabled at `e44db55`. Entire also imported this project's earlier Claude Code session (`8cdad8b4…`) as 19 `import` checkpoints. All of them are attached to `5ad8d7f`, the HEAD at import time, not to the commits that wrote the code. So `entire why targets/refundbot/tools.ts:87` reports the line as `[HU]` (no checkpoint) at `cf0ceac`.
- **Bulwark's transcript match recovers the real session for RefundBot's weak links.** The imported transcript in checkpoint `01M4JHF2GWEP2029BVPZ8A9WQ1` (prompt "start building something for this app", 09:14Z) contains the `Write` of `targets/refundbot/tools.ts` at 09:17:08Z. That write includes line 87 verbatim, and it happened 3 minutes before commit `cf0ceac` (09:20:18Z). All seven RefundBot findings (`tools.ts:79`, `:87`, `:101` and `agent.ts:56`) resolve this way. They are reported as `match: transcript` and are never presented as a trailer link.
- **The exact checkpoint path is real.**
  - `docs/FEATURES.md:63` (the Tier D section) resolves through `entire why` to checkpoint `01M4MGGKEQXJR07RTC3SAJQ3P8` on commit `e44db55`, with its session and prompt.
  - The feature's own commit, `752c56e`, was made from a Claude Code subagent. Entire's `prepare-commit-msg` hook added `Entire-Checkpoint: 01M4MH8FJRZJJ7TFJQB0Y6S14V`, and the post-commit hook wrote `refs/entire/checkpoints/4V/01M4MH8FJRZJJ7TFJQB0Y6S14V`. That checkpoint has no top-level prompt (the work was done by subagents). Bulwark reads the subagent transcripts stored in it and names the task that wrote the line: `npm run provenance -- bulwark/provenance/entire.ts:1` → "via subagent task "Entire bug provenance"". Entire marks this link `session_fallback` (the new file isn't in the checkpoint's `files_touched`), and Bulwark says so.
- **Some lines fall back to git.** For example, `bulwark/report/reports.ts:9` (commit `ae0406c`) has no trailer, and no imported transcript wrote that exact line. That work was done by subagents, whose transcripts were not part of the import. Bulwark reports the commit, author and date, and says no session could be linked.
- **The residual findings in the PR body ("Remaining risk") get no provenance.** They point at the patched copy in `.bulwark/runs/<id>/ws`, which is not committed.
