// Sends one small neatlogs trace of a given shape and prints its trace id + send time.
// usage: tsx probe-send.mts <shape> <lifetime: shutdown|flush-stay|stay>
const NL = '/Users/mrnetwork/Bulwark/.claude/worktrees/agent-ac0eedf14ccafb13e/node_modules/neatlogs/dist/index.mjs';
const { init, trace, span, flush, shutdown, getDeliveryDiagnostics } = await import(NL);
const [shape, lifetime = 'shutdown'] = process.argv.slice(2);
await init({ apiKey: process.env.NEATLOGS_API_KEY, workflowName: 'bulwark-readback-probe', tags: ['bulwark', 'probe'], mask: (s: unknown) => s });
const tool = span({ kind: 'TOOL', name: 'lookup_order' }, async (id: string) => ({ id, total: 49 }));
const name = `bulwark-readback-probe-${shape}-${lifetime}-${Date.now()}`;
let traceId = '';
const sid = `bulwark-readback-probe-${Date.now()}`;
if (shape === 'chain') {
  await trace({ name, kind: 'CHAIN' }, async (s: any) => { traceId = s.spanContext().traceId; await tool('ord_1'); });
} else if (shape === 'workflow') {
  await trace({ name, kind: 'WORKFLOW' }, async (s: any) => { traceId = s.spanContext().traceId; await tool('ord_1'); });
} else if (shape === 'workflow-session') {
  await trace({ name, kind: 'WORKFLOW', sessionId: sid, sessionFeatureName: 'bulwark-loop' }, async (s: any) => { traceId = s.spanContext().traceId; await tool('ord_1'); });
} else if (shape === 'bulwark') {
  // phase WORKFLOW (session) → experiment WORKFLOW → trial CHAIN → TOOL; the trial reports its own traceId
  await trace({ name, kind: 'WORKFLOW', sessionId: sid, sessionFeatureName: 'bulwark-loop' }, async () =>
    trace({ name: 'experiment: probe', kind: 'WORKFLOW' }, async () =>
      Promise.all([0, 1].map(() => trace({ name: 'bulwark.trial', kind: 'CHAIN' }, async (s: any) => { traceId = s.spanContext().traceId; await tool('ord_1'); }))),
    ),
  );
}
const sent = Date.now();
if (lifetime === 'shutdown') await shutdown();
else if (lifetime === 'flush-stay') await flush();
console.log(JSON.stringify({ shape, lifetime, name, traceId, sent, diag: getDeliveryDiagnostics?.() }));
if (lifetime !== 'shutdown') setTimeout(() => process.exit(0), 15 * 60_000);

