// Polls neatlogs for each trace id until 200 with spans; logs status transitions with elapsed time.
// usage: tsx probe-poll.mts <sentMs> <traceId>... (max 25 min)
const key = process.env.NEATLOGS_API_KEY!;
const [sentArg, ...ids] = process.argv.slice(2);
const sent = Number(sentArg);
const last: Record<string, string> = {};
const done = new Set<string>();
const deadline = Date.now() + 25 * 60_000;
while (done.size < ids.length && Date.now() < deadline) {
  for (const id of ids) {
    if (done.has(id)) continue;
    try {
      const res = await fetch(`https://ingest.neatlogs.com/api/traces/v3/${id}`, { headers: { 'x-api-key': key } });
      const j: any = await res.json().catch(() => ({}));
      const sig = `${res.status} ${j.finalizationStatus ?? ''} spans=${j.spans?.length ?? '-'} ${JSON.stringify(j.ingestionDiagnostics ?? j.error ?? '')}`;
      if (sig !== last[id]) {
        console.log(`${((Date.now() - sent) / 1000).toFixed(0)}s ${id} ${sig}`);
        last[id] = sig;
      }
      if (res.status === 200 && j.spans?.length) {
        done.add(id);
        console.log(`DONE ${id} name=${j.name} status=${j.status} spans=${j.spans.length} detections=${(j.detections ?? []).length} keys=${Object.keys(j).join(',')}`);
      }
    } catch (e) {
      console.log('err', String(e));
    }
  }
  await new Promise((r) => setTimeout(r, 5000));
}
console.log('END', done.size, '/', ids.length);

