// Observe step: before Blue proposes a fix, read a failing trial's trace back
// from neatlogs and hand Blue what neatlogs recorded. Bounded by a wait budget,
// never throws, and degrades to "unavailable" without a key.

import { focusTrial, readTrace, summarizeTrace, type Fetcher, type ReadResult, type ReadStatus } from './neatlogs';

export interface ObserveCandidate {
  seed: number;
  traceId?: string;
  /** Where the failing trial came from: the BEFORE scorecard, the Judge's baseline, or a traced re-run. */
  source: 'before' | 'judge' | 'rerun';
}

export interface ObserveRecord {
  fault: string;
  traceId?: string;
  seed?: number;
  source?: ObserveCandidate['source'];
  status: ReadStatus;
  /** Spans of the failing trial (the trace is narrowed to it). */
  spans: number;
  detections: number;
  waitedMs: number;
  reason?: string;
  stage?: string;
}

export interface ObserveOptions {
  fault: string;
  /** Failing trials, best first (earliest traced first: it has had the most time to finalize). */
  candidates: ObserveCandidate[];
  /** Re-runs one failing seed traced and returns its trace id (trials replay deterministically from a seed). */
  rerun?: (seed: number) => Promise<string | undefined>;
  waitMs: number;
  pollMs?: number;
  fetcher?: Fetcher;
  /** Reads already made in this run, by trace id; phase traces hold every fault's trials, so one read serves many faults. */
  cache?: Map<string, ReadResult>;
}

export async function observeFailure(o: ObserveOptions): Promise<{ record: ObserveRecord; evidence?: string }> {
  const base = { fault: o.fault, spans: 0, detections: 0, waitedMs: 0 };
  if (o.waitMs <= 0) return { record: { ...base, status: 'unavailable', reason: 'neatlogs read-back disabled (wait 0)' } };
  if (!process.env.NEATLOGS_API_KEY) return { record: { ...base, status: 'unavailable', reason: 'NEATLOGS_API_KEY not set' } };

  let pick = o.candidates.find((c) => c.traceId);
  if (!pick && o.rerun && o.candidates.length) {
    const seed = o.candidates[0].seed;
    try {
      const traceId = await o.rerun(seed);
      if (traceId) pick = { seed, traceId, source: 'rerun' };
    } catch {
      // fall through: no trace to read
    }
  }
  if (!pick?.traceId) return { record: { ...base, status: 'unavailable', reason: 'no traced failing trial' } };

  const cached = o.cache?.get(pick.traceId);
  // A trace already read is reused. One that was still pending gets a single re-check, not a second full wait.
  const res = cached?.status === 'read' ? cached : await readTrace(pick.traceId, { waitMs: cached ? 0 : o.waitMs, pollMs: o.pollMs, fetcher: o.fetcher });
  o.cache?.set(pick.traceId, res);
  const record: ObserveRecord = {
    ...base,
    traceId: pick.traceId,
    seed: pick.seed,
    source: pick.source,
    status: res.status,
    waitedMs: cached?.status === 'read' ? 0 : res.waitedMs,
    ...(res.reason ? { reason: res.reason } : {}),
    ...(res.stage ? { stage: res.stage } : {}),
  };
  if (res.status !== 'read' || !res.trace) return { record };
  const focus = { fault: o.fault, seed: pick.seed };
  const spans = focusTrial(res.trace, focus);
  record.spans = spans.length;
  record.detections = [...(res.trace.detections ?? []), ...(res.trace.traceDetections ?? []), ...spans.flatMap((s) => s.detections ?? [])].length;
  return { record, evidence: summarizeTrace(res.trace, { focus }) };
}

/** The postmortem / CLI line for one observe step. */
export function describeObserve(r: ObserveRecord): string {
  if (r.status === 'read') return `Diagnosed from neatlogs trace ${r.traceId} (${r.spans} spans, ${r.detections} detections; failing trial seed ${r.seed} from the ${r.source === 'rerun' ? 'traced re-run' : r.source === 'judge' ? "Judge's baseline" : 'BEFORE scorecard'}).`;
  if (r.status === 'pending') return `neatlogs trace ${r.traceId} not finalized in time (${r.reason ?? 'pending'}${r.stage ? `, last state: ${r.stage}` : ''}); used local evidence.`;
  return `neatlogs read-back unavailable (${r.reason ?? 'unknown'}); used local evidence.`;
}

